def transform(grid):
    h, w = len(grid), min(map(len, grid))
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != background)
    fill = 3
    # Join marker points with horizontal and vertical segments.
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        if xs:
            for c in range(min(xs), max(xs) + 1):
                if grid[r][c] != marker:
                    out[r][c] = fill
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
